  -- Reads a team set (none = the active one).
  function BattleBayDeluxe.active_team_read(from)
    local set = from or VRFW.host.command(B.VS_SET)
    if type(set) ~= "number" or set < 0 then
      return nil, "no active team set (CMND_GET_VS_USE_TEAM_SET " .. tostring(set) .. ")"
    end
    local d = { set = set, lineup = {}, members = {}, captain = 0, tactics = {}, name = "" }
    local parts = {}
    for k = 0, B.MEMBERS - 1 do
      local has, hdl = VRFW.host.command(B.MEMBER, set, B.TEAM_TYPE, k, 0)
      if has and type(hdl) == "number" and hdl ~= 0 then
        local hasp, pos = VRFW.host.command(B.MEMBER, set, B.TEAM_TYPE, k, 1)
        if hasp and type(pos) == "number" and pos >= 0 and pos <= B.COACH_POSITION and d.members[pos] == nil then
