        end
        if hasp and type(pos) == "number" and pos >= 0 and pos <= B.SQUAD_LAST and d.lineup[pos] == nil then
          local card = VRFW.host.command(B.STATUS, hdl, 4)
          card = VRFW.ids.unsigned(card) or 0
          if card ~= 0 then
            d.lineup[pos] = card
            parts[#parts + 1] = string.format("%d:%.0f", pos, card)
            local hask, captain = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_CAPTAIN, hdl)
            if hask and captain == true then
              d.captain = card
            end
          end
        end
      end
    end
    if #parts == 0 then
      return nil, "the team set " .. set .. " has no players"
    end
    local hasf, formation = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_FORMATION)
    if hasf and type(formation) == "number" and formation ~= 0 then
      d.formation = formation
    end
    local hase, emblem = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_EMBLEM, 0)
    if hase and type(emblem) == "number" and emblem ~= 0 then
      d.emblem = emblem
    end
    local hasu, uniform = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_UNIFORM)
    if hasu and type(uniform) == "number" and uniform ~= 0 then
      d.uniform = uniform
    end
    local hasn, name = VRFW.host.command(B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_NAME)
    if hasn and type(name) == "string" then
      d.name = name
    end
